{
  "command": "curl -s -m 60 \"https://izw1.caltech.edu/ACE/ASC/level2/lvl2DATA_SWICS_2.0.html\" | grep -i -E \"href\" | grep -i -E \"2025|2024|sw2|swics\" | head; ",
  "description": "Find SWICS 2.0 2025 data links"
}

{
  "command": "curl -s -m 60 \"https://izw1.caltech.edu/ACE/ASC/level2/lvl2DATA_SWICS_2.0.html\" | grep -i -B2 -A2 \"Year 2025\" | head -20",
  "description": "Show HTML around Year 2025 link"
}

{
  "command": "curl -s -m 60 \"https://izw1.caltech.edu/ACE/ASC/level2/lvl2DATA_SWICS_2.0.html\" | sed -n '/lvl2_data_select/,/\\/FORM/p' | head -40; curl -s -m 120 \"https://izw1.caltech.edu/cgi-bin/lvl2_data_select.pl?command=ss2_data_2hr_year2025.hdf\" | head -c 3000",
  "description": "Inspect SWICS 2.0 form and request 2025 data"
}

{
  "command": "curl -s -m 120 \"https://izw1.caltech.edu/cgi-bin/dib/rundibviewss2l2/ACE/ASC/DATA/level2/ss2?ss2_data_2hr_year2025.hdf!hdfref;tag=1962,ref=3,s=0\" | sed 's/<[^>]*>/ /g' | tr -s ' \\n' | head -c 4000; curl -s -m 120 \"https://izw1.caltech.edu/cgi-bin/dib/rundibviewss2l2/ACE/ASC/DATA/level2/ss2?ss2_data_2hr_year2025.hdf!hdfref;tag=1962,ref=3,s=0\" | grep -i -E \"input|form|select\" | head -40",
  "description": "Inspect ASC data browser form for SWICS 2025"
}

{
  "command": "Q=\"SELECT TOP 20 data_item_id,descriptor,level,begin_time,end_time FROM v_sc_data_item WHERE instrument='SWA' AND descriptor LIKE '%HIS%' AND begin_time > '2025-09-01' ORDER BY begin_time\"; curl -s -m 120 -G \"https://soar.esac.esa.int/soar-sl-tap/tap/sync\" --data-urlencode \"REQUEST=doQuery\" --data-urlencode \"LANG=ADQL\" --data-urlencode \"FORMAT=csv\" --data-urlencode \"QUERY=$Q\" | head -30; Q2=\"SELECT descriptor,level,MAX(end_time) AS last FROM v_sc_data_item WHERE instrument='SWA' AND descriptor LIKE '%HIS%' GROUP BY descriptor,level\"; curl -s -m 120 -G \"https://soar.esac.esa.int/soar-sl-tap/tap/sync\" --data-urlencode \"REQUEST=doQuery\" --data-urlencode \"LANG=ADQL\" --data-urlencode \"FORMAT=csv\" --data-urlencode \"QUERY=$Q2\" | head -30",
  "description": "Query ESA SOAR for SolO HIS products in late 2025"
}

{
  "command": "Q2=\"SELECT descriptor,level,MAX(end_time) AS tend, COUNT(*) AS n FROM v_sc_data_item WHERE instrument='SWA' GROUP BY descriptor,level\"; curl -s -m 120 -G \"https://soar.esac.esa.int/soar-sl-tap/tap/sync\" --data-urlencode \"REQUEST=doQuery\" --data-urlencode \"LANG=ADQL\" --data-urlencode \"FORMAT=csv\" --data-urlencode \"QUERY=$Q2\" | head -60",
  "description": "List SOAR SWA products with latest end time"
}

{
  "command": "curl -s -m 60 \"https://www.ngdc.noaa.gov/dscovr/data/2025/11/\" | grep -o 'href=\"[^\"]*f1m[^\"]*\"' | head -5; curl -s -m 60 \"https://www.ngdc.noaa.gov/dscovr/data/2025/11/\" | grep -o 'href=\"[^\"]*\"' | sed 's/href=//' | awk -F_ '{print $2}' | sort | uniq -c | head -20",
  "description": "Check NOAA NCEI DSCOVR archive for Nov 2025"
}

{
  "command": "curl -s -m 60 -i \"https://www.ngdc.noaa.gov/dscovr/data/2025/11/\" | head -30; curl -s -m 60 -i \"https://www.ngdc.noaa.gov/dscovr/portal/index.html\" | head -5",
  "description": "Inspect DSCOVR archive HTTP response"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/data/raw/hapi; cat fetch.log; for d in */; do echo \"$d $(ls $d | wc -l) $(du -sh $d | cut -f1)\"; done",
  "description": "Check download progress"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/data/raw/hapi; ls -la STA_L2_PLA_1DMAX_1MIN PSP_SWP_SPC_L3I | head; curl -s -m 60 \"https://cdaweb.gsfc.nasa.gov/hapi/data?id=STA_L2_PLA_1DMAX_1MIN&parameters=proton_number_density&time.min=2025-11-01T00:00:00Z&time.max=2025-11-01T00:10:00Z&format=csv\"; echo; curl -s -m 60 \"https://cdaweb.gsfc.nasa.gov/hapi/data?id=STA_L2_PLA_1DMAX_1MIN&parameters=error,caution,attitude_flag,proton_number_density&time.min=2025-11-01T00:00:00Z&time.max=2025-11-01T00:10:00Z&format=csv\"; curl -s -m 60 \"https://cdaweb.gsfc.nasa.gov/hapi/data?id=STA_L2_PLA_1DMAX_1MIN&parameters=proton_number_density&time.min=2025-06-01T00:00:00Z&time.max=2025-06-01T00:10:00Z&format=csv\"; curl -s -m 60 \"https://cdaweb.gsfc.nasa.gov/hapi/data?id=STA_L2_PLA_1DMAX_1HR&parameters=proton_number_density&time.min=2025-11-01T00:00:00Z&time.max=2025-11-01T05:10:00Z&format=csv\"",
  "description": "Investigate empty STEREO-A PLASTIC chunks"
}

{
  "command": "for p in error caution attitude_flag proton_bulk_speed proton_temperature proton_Vr_RTN proton_Vt_RTN proton_Vn_RTN; do echo \"$p: $(curl -s -m 60 \"https://cdaweb.gsfc.nasa.gov/hapi/data?id=STA_L2_PLA_1DMAX_1MIN&parameters=$p&time.min=2025-11-01T00:00:00Z&time.max=2025-11-01T00:02:00Z&format=csv\" | tr '\\n' ' ' | head -c 200)\"; done",
  "description": "Test STA PLASTIC parameters individually"
}

